        \begin{matrix}
            \overbrace{XYZ}^{\mbox{$R$}}\\ \\ \\ \\ \\ \\ \\ \\
            \underbrace{pqr}_{\mbox{$S$}} \\
        \end{matrix}} 
    \begin{matrix}                        
        \vphantom{a}

p+1\left\{\vphantom{\begin{matrix} * \\ \vdots \\ * \\ * \vspace{0.5cm} \end{matrix}}\right. \vspace{0.1cm}\\ 

p-1\left\{\vphantom{\begin{matrix} * \\ \vdots \\ * \end{matrix}}\right.
    \end{matrix} 
    \begin{pmatrix}
        \mathrlap{\smash{\overbrace{\phantom{ 
    \begin{matrix} *     & \ldots &     * \hspace{0.1cm} \end{matrix}}}^{\mbox{$p-1$}}}}*     & \ldots &     * \hspace{0.1cm}& \mathrlap{\smash{\overbrace{\phantom{ 
