\label{lem:49}
Consider $q^{\mathbf{G}^p}(z) = g_0 z^{2p} + g_1 z^{2p-1} + \ldots + g_1 z + g_0 $, a self-reciprocal polynomial of degree $2p$. Let $\{x_1,\ldots,x_p\}$ denote the roots of its Chebyshev transform $\mathcal{T} q^{\mathbf{G}^p}$. Assuming $g_0 \ne 0$, the following formulas are valid

\begin{align*}
   \prod_{j=1}^p (x_j-2) = (-1)^p \, \frac{q^{\mathbf{G}^p}(1)}{g_0}, \quad \quad \quad \prod_{j=1}^p (x_j+2) = \frac{q^{\mathbf{G}^p}(-1)}{g_0}.
\end{align*}

\label{prop:410}
If the family of matrices $\{ \mathbf{G}_n^p \}_n$ in \eqref{eq:44} is weakly well-con-\\ ditioned, and if $p>1$ not all zeros of the associated polynomial $q^{\mathbf{G}^p}$, as defined in \eqref{eq:45}, are on the boundary of the unit circle, then $q^{\mathbf{G}^p}$ satisfies the following condition

\begin{equation} \label{eq:48}
	(-1)^p q^{\mathbf{G}^p}(-1) q^{\mathbf{G}^p}(1) \le 0.
\end{equation}

\label{prop:51}
For $p \ge 1$ and $\theta \in [-\pi,\pi]$, let the functions $M_p, B_p, D_p : [-\pi,\pi] \to \mathbb{R}$ be defined as

\begin{align*}
	M_p(\theta)  = (2-2\cos \theta)^{p+1} \sum_{j \in \mathbb{Z}} \frac{1}{(\theta + 2j\pi)^{2p+2}}, & \quad 
 B_p(\theta)  = -(2-2\cos \theta)^{p+1} \sum_{j \in \mathbb{Z}} \frac{1}{(\theta + 2j\pi)^{2p}},
	\\  & \hspace{-1.5cm} D_p(\theta) = (-1)^p (2-2\cos \theta)^p.
\end{align*}

Then, the following relations hold true 

\begin{align}
    \Phi_{2p+1}(p+1) + \sum_{j=1}^{p} \Phi_{2p+1}(p+1-j) (e^{-\mathrm{i} j \theta}+e^{\mathrm{i} j \theta}) & = M_p(\theta), \label{eq:51}
	\\ \partial_s^2 \Phi_{2p+1}(p+1) + \sum_{j=1}^{p}  \partial_s^2 \Phi_{2p+1}(p+1-j) (e^{-\mathrm{i} j \theta} + e^{\mathrm{i} j \theta}) & = B_p(\theta),
	\\ \partial_s^{2p} \Phi_{2p+1}(p+1) + \sum_{j=1}^{p} \partial_s^{2p} \Phi_{2p+1}(p+1-j) (e^{-\mathrm{i} j \theta} + e^{\mathrm{i} j \theta})  & = D_p(\theta).
\end{align}

Therefore, we can express $q^{\mathbf{K}^p(\rho,\delta)}(e^{\mathrm{i} \theta})$ as

\begin{equation} \label{eq:54}
	q^{\mathbf{K}^p(\rho,\delta)}(e^{\mathrm{i} \theta}) = e^{\mathrm{i} p \theta}\left( B_p(\theta) + \rho\left(M_p(\theta) + \delta (-1)^p D_p(\theta) \right) \right).
\end{equation}

There is already a proof for the explicit expressions of $M_p(\theta)$ and $B_p(\theta)$ in \cite[Lemmas 7 and 6]{GaroniManniPelosiSerraCapizzanoSpeleers2014}. For the sake of completeness, we report the details for $M_p(\theta)$, and present a different proof for $B_p(\theta)$, which is useful for calculating $D_p(\theta)$.

We recall that the Fourier transform of a cardinal spline $\Phi_p$ is

\begin{equation*}
	\widehat \Phi_p(\xi) = \left(\frac{1-e^{-\mathrm{i} \xi}}{\mathrm{i} \xi} \right)^{p+1}, \quad \left| \widehat \Phi_p(\xi) \right|^2 = \left(\frac{2-2\cos \xi}{\xi^2} \right)^{p+1}, \quad \quad \xi \in \mathbb{R}
\end{equation*}

(see \cite[Example 3.4]{Chui1992}), and satisfies the hypothesis of a Poisson summation formula \cite[Theorem 2.28]{Chui1992}, i.e., for all $\theta \in [-\pi,\pi]$

\begin{equation*}
	\sum_{j \in \mathbb{Z}} \left(\int_{\mathbb{R}} \Phi_p(s) \Phi_p(s+j) \dd s\right) e^{\mathrm{i} j \theta}  = \sum_{j \in \mathbb{Z}} \left| \widehat{\Phi}_p(\theta+2j\pi) \right|^2.
\end{equation*}

To show \eqref{eq:51}, recalling \eqref{eq:37} and \eqref{eq:38}, we compute for $\theta \in [-\pi,\pi]$, 

\begin{align*}
	\Phi_{2p+1}(p+1) & + \sum_{j=1}^{p}\Phi_{2p+1}(p+1-j) (e^{-\mathrm{i} j \theta}+e^{\mathrm{i} j \theta}) = \sum_{j \in \mathbb{Z}} \Phi_{2p+1}(p+1-j) e^{\mathrm{i} j \theta}
    \\ & = \sum_{j \in \mathbb{Z}} \left(\int_{\mathbb{R}} \Phi_p(s) \Phi_p(s+j) \dd s\right) e^{\mathrm{i} j \theta} = \sum_{j \in \mathbb{Z}} \left| \widehat{\Phi}_p\left(\theta+2j\pi\right) \right|^2
    \\ & = (2-2\cos \theta)^{p+1} \sum_{j \in \mathbb{Z}} \frac{1}{(\theta+2j\pi)^{2(p+1)}}.
\end{align*}

Using the recurrence relation for derivatives of cardinal splines \cite[Theorem 4.3]{Chui1992} 

\begin{equation*}
	\partial_s^k \Phi_p(s) = \partial_s^{k-1} \Phi_{p-1}(s) - \partial_s^{k-1} \Phi_{p-1}(s-1),
\end{equation*}

and considering that $e^{\mathrm{i} j \theta} - 2e^{\mathrm{i} (j+1) \theta} + e^{\mathrm{i} (j+2) \theta} = e^{\mathrm{i} j \theta} (1-e^{\mathrm{i} \theta})^2 = -e^{\mathrm{i} (j+1) \theta}(2-2\cos \theta)$, we can compute

\begin{align*}
	 \partial_s^2 \Phi_{2p+1}(p+1) & + \sum_{j=1}^{p} \partial_s^2 \Phi_{2p+1}(p+1-j) (e^{-\mathrm{i} j \theta}+e^{\mathrm{i} j \theta}) 
  \\ &= \sum_{j \in \mathbb{Z}} \partial_s^2 \Phi_{2p+1}(p+1-j) e^{\mathrm{i} j \theta}
    \\ & = \sum_{j \in \mathbb{Z}} \left(\partial_s \Phi_{2p}(p+1-j)-\partial_s \Phi_{2p}(p-j)\right) e^{\mathrm{i} j \theta}
	 \\ & = \sum_{j \in \mathbb{Z}} \left(\Phi_{2p-1}(p+1-j)-2\Phi_{2p-1}(p-j)+\Phi_{2p-1}(p-j-1)\right)  e^{\mathrm{i} j \theta}
	 \\ & = -(2-2\cos \theta)\sum_{j \in \mathbb{Z}} \Phi_{2p-1}(p+1-j) e^{\mathrm{i} (j+1) \theta} 
     \\ & = -(2-2\cos \theta)\sum_{j \in \mathbb{Z}} \Phi_{2p-1}(p-j) e^{\mathrm{i} j \theta}
     \\ & = -(2-2\cos \theta)^{p+1} \sum_{j \in \mathbb{Z}} \frac{1}{(\theta + 2j\pi)^{2p}},
\end{align*}

where in the last equality we used the same procedures as in the proof for $M_p(\theta)$. Similarly, we can iteratively make the same steps as before to show that 

\begin{align*}
	\partial_s^{2p} \Phi_{2p+1}(p+1) + \sum_{j=1}^{p} \partial_s^{2p} \Phi_{2p+1}(p+1-j) (e^{-\mathrm{i} j \theta}+e^{\mathrm{i} j \theta})
	& = (-1)^p (2-2\cos \theta)^p \sum_{j \in \mathbb{Z}} \Phi_1(1-j)e^{\mathrm{i} j \theta} 
	\\ & = (-1)^p (2-2\cos \theta)^{p}.
\end{align*}

\label{cor:54}
For $p \ge 1$, let $M_p, B_p, D_p$ be the functions defined in Proposition \ref{prop:51}. It holds true that $M_p(0)=1$, and $B_p(0) = D_p(0) = 0$. Furthermore, we have

\begin{align*}
	M_p(\pi) = \frac{2}{\pi^{2(p+1)}} (2^{2(p+1)}-1)  \zeta(2(p+1)), & \quad  \quad 
	B_p(\pi) = -2^2M_{p-1}(\pi) = -\frac{2^3}{\pi^{2p}} (2^{2p}-1) \zeta(2p),
	\\ & \hspace{-1cm} D_p(\pi) = (-1)^p 2^{2p},
\end{align*}

where $\zeta$ is the Riemann zeta function. Therefore, we have $q^{\mathbf{K}^p(\rho,\delta)}(1) = \rho$ and

\begin{equation*}
\begin{aligned}
	q^{\mathbf{K}^p(\rho,\delta)}(-1) =  (-1)^p \Biggl( -\frac{2^3}{\pi^{2p}}(2^{2p}-1) \zeta(2p)
	 + \rho \left(\frac{2}{\pi^{2(p+1)}}(2^{2(p+1)}-1) \zeta\left(2(p+1)\right) + \delta 2^{2p}\right)\Biggr).
\end{aligned}	
\end{equation*}

The limits as $\theta \to 0$ and the values at $\theta=\pi$ are readily obtained from the explicit expressions of $M_p, B_p, D_p$ in Proposition \ref{prop:51}:

\begin{align} \label{eq:55}
	&\lim_{\theta \to 0} M_p(\theta) = 1, \quad \lim_{\theta \to 0} B_p(\theta) = 0, \quad \lim_{\theta \to 0} D_p(\theta) = 0;
\end{align}


\begin{equation*}
\begin{aligned} 
	M_p(\pi) =  2^{2(p+1)} \sum_{j \in \mathbb{Z}} \frac{1}{(\pi + 2j\pi)^{2(p+1)}}&, \quad B_p(\pi) = -2^{2(p+1)} \sum_{j \in \mathbb{Z}} \frac{1}{(\pi + 2j\pi)^{2p}}, \quad D_p(\pi)= (-1)^p 2^{2p}.
\end{aligned}
\end{equation*}

It remains to explicitly calculate the two infinite sums. We have, for $m \ge 1$,

\begin{align*}
	\sum_{j \in \mathbb{Z}} \frac{1}{(\pi+2j \pi)^{2m}} & = \frac{1}{\pi^{2m}} \sum_{j \in \mathbb{Z}} \frac{1}{(1+2j)^{2m}}
	\\ & = \frac{1}{\pi^{2m}} \sum_{j=0}^\infty \frac{1}{(1+2j)^{2m}} + \frac{1}{\pi^{2m}} \sum_{j=1}^{\infty} \frac{1}{(2j-1)^{2m}}
	\\ & =  \frac{2}{\pi^{2m}} \sum_{j=1}^{\infty} \frac{1}{(2j-1)^{2m}}
	 \\ &= \frac{1}{\pi^{2m}} \frac{(2^{2m}-1)}{2^{2m-1}} \zeta(2m),
\end{align*}

where for the last equality, we used \cite[Equation 0.233.5]{GradshteynRyzhik2015}. The expressions for $q^{\mathbf{K}^p(\rho,\delta)}(\pm 1)$ follow from \eqref{eq:54}.

The cardinal splines satisfy the property of partition for unity (see \cite[Theorem 4.3]{Chui1992}), meaning $\sum_{j \in \mathbb{Z}} \Phi_p(s-j) = 1$, and consequently $\sum_{j \in \mathbb{Z}} \partial_s \Phi_p(s-j) = 0$. Therefore, $q^{\mathbf{K}^p(\rho,\delta)}(1)$ can be computed directly without Proposition \ref{prop:51} as 

\begin{equation*}
\begin{aligned}
	q^{\mathbf{K}^p(\rho,\delta)}(1) = \sum_{j \in \mathbb{Z}} \partial_s^2 \Phi_{2p+1}(p+1-j) + \rho \Biggl(\sum_{j \in \mathbb{Z}} \Phi_{2p+1}(p+1-j) + \delta (-1)^p \sum_{j \in \mathbb{Z}} \partial_s^{2p} \Phi_{2p+1}(p+1-j)\Biggr) = \rho.
\end{aligned}
\end{equation*}

\label{prop:56}
Let $p \ge 1$ and define the quantities

\begin{equation} \label{eq:56}
\begin{aligned}
	\delta_p & = -\frac{M_p(\pi)}{(-1)^p D_p(\pi)} =  -\frac{(2^{2(p+1)}-1)}{2^{2p-1} \pi^{2(p+1)}} \zeta\left(2(p+1)\right), \quad \rho_p & = - \frac{B_p(\pi)}{M_p(\pi)} = 4 \pi^2 \frac{(2^{2p}-1)}{(2^{2(p+1)}-1)} \frac{\zeta(2p)}{\zeta(2(p+1))}
	\end{aligned}
\end{equation}

with $M_p, B_p$ and $D_p$ as in Proposition \ref{prop:51}. If $p>1$, assume that not all the zeros of $q^{\mathbf{K}^p(\rho,\delta)}$ are on the boundary of the unit circle. Then, the following statements are valid.

\begin{itemize}

\item If the family of matrices $\{\mathbf{K}_n^p(\rho,\delta)\}_n$ is weakly well-conditioned for all $\rho > 0$, then $\delta \le \delta_\rho$. 

\item If the family of matrices $\{\mathbf{K}^p_n(\rho,0)\}_n$ is weakly well-conditioned, then $\rho \le \rho_p$.  
\end{itemize}

The result directly follows by Proposition \ref{prop:410}, Corollaries \ref{cor:54} and Theorem \ref{th:45}. Specifically, if the family of matrices $\{\mathbf{K}^p_n(\rho,\delta)\}_n$ is weakly well-conditioned, then we have $(-1)^p q^{\mathbf{K}^p(\rho,\delta)}(-1)q^{\mathbf{K}^p(\rho,\delta)}(1) \le 0$, which is equivalent to 

\begin{equation*}
    B_p(\pi) + \rho(M_p(\pi) + \delta (-1)^p D_p(\pi)) \le 0
\end{equation*}

or explicitly,
\begin{equation*}
	-\frac{2^3}{\pi^{2p}}(2^{2p}-1) \zeta(2p) + \rho \left(\frac{2}{\pi^{2(p+1)}}(2^{2(p+1)}-1) \zeta\left(2(p+1)\right) + \delta 2^{2p}\right) \le 0.
\end{equation*}

Note that $\zeta(m) \to 1$ as $m \to +\infty$. This can observed from the inequality 

\begin{equation*}
	1 \le \zeta(m) = \sum_{n=1}^\infty n^{-m} = 1 + \sum_{n=2}^\infty n^{-m} \le 1 +\int_1^\infty x^{-m} \dd x = 1+ \frac{1}{m-1}.
\end{equation*}

Consequently, we deduce $\rho_p \to \pi^2$ and $\delta_p \sim -8/\pi^2 \, \pi^{-2p} \to 0$ as $p \to \infty$. These results are consistent with those obtained in \cite[Figure 1]{FLMS2023}, where the trend $\delta_p \approx -10^{-p}$ was observed. Furthermore, the constants $\rho_1$ and $\delta_1$ are exactly the same as those obtained in \cite{SZ2019}. Some values of $\rho_p$ and $\delta_p$ are reported in Table \ref{tab:1}.

