            * & \ldots & * &  
  \begin{tikzpicture}[baseline=-0.5ex]
    \draw (0,0) circle (0.5em);
    \node at (0,0) {$*$};
  \end{tikzpicture} 
 & \ldots &  
  \begin{tikzpicture}[baseline=-0.5ex]
    \draw (0,0) circle (0.5em);
    \node at (0,0) {$*$};
  \end{tikzpicture} 
 \\
            & \ddots & \vdots & \vdots & & \vdots \\
            & & * &  
  \begin{tikzpicture}[baseline=-0.5ex]
    \draw (0,0) circle (0.5em);
    \node at (0,0) {$*$};
  \end{tikzpicture} 
 & \ldots &  
  \begin{tikzpicture}[baseline=-0.5ex]
    \draw (0,0) circle (0.5em);
    \node at (0,0) {$*$};
  \end{tikzpicture} 

        \end{matrix}
    \end{array}
    \right)
    \hspace{-0.2cm}
    \begin{matrix}
    \phantom{ 
\left.\vphantom{\begin{matrix} * \\  \\ \\ \\ \\ \\ \\  \vspace{0.15cm} \\ \\ \\ \\ \\  *  \end{matrix}}\right\}k} 
        \\  
\left.\vphantom{\begin{matrix} * \\ \vspace{0.15cm} \\ *  \end{matrix}}\right\}m \vspace{0.05cm} \\ 

\left.\vphantom{\begin{matrix} * \\ \vspace{0.1cm} \\ *  \end{matrix}}\right\}k
        \vspace{0.1cm}
    \end{matrix}
    \hspace{-0.5cm},
\end{equation*}

with the same entries of $\widehat{\mathbf{C}}_n$ in the bottom-right sub-block of size $k \times k$ from the $(n-m-k)^{\operatorname{th}}$ to the $(n-m-1)^{\operatorname{th}}$ columns, and whose other entries in this block (the circled ones) are such that each $(\mathbf{C}_n^{(3)})^{-1}$ exists for $n$ sufficiently large.
\end{itemize}

At each step $j=1,\ldots,4$ we show that

\begin{equation} \label{eq:A3}
    (\mathbf{C}_n^{(j)})^{-1} = (\mathbf{C}_n^{(j-1)})^{-1} + \mathbf{H}_n^{(j)},
\end{equation}

for four matrices $\mathbf{H}_n^{(j)} \in \mathbb{R}^{n \times n}$ such that

\begin{equation} \label{eq:A4}
    \| \mathbf{H}_n^{(j)}\|_{1} = \mathcal{O}\bigl(\| (\mathbf{C}_n^{(j-1)})^{-1}\|_{1}\bigr) \quad \quad j = 1,\ldots,4     
\end{equation}

for $n$ sufficiently large. Combining the four steps we deduce

\begin{equation} \label{eq:A5}
    \widehat{\mathbf{C}}_n^{-1} = \mathbf{C}^{-1}_n + \mathbf{H}_n^{(1)} + \mathbf{H}_n^{(2)} + \mathbf{H}_n^{(3)} + \mathbf{H}_n^{(4)},
\end{equation}

and the same conditioning behaviour for the families $\{ \mathbf{C}_n \}_n$ and $\{\widehat{\mathbf{C}}_n \}_n$.

Let $z_1,\ldots,z_{m+k}$ be the zeros of the polynomial $q^{\mathbf{C}}$ associated with the family $\{\mathbf{C}_n\}_n$, defined in \eqref{eq:42}, ordered such that $0 < | z_1 | \le \ldots \le | z_{m+k} |$. Associated with these zeros we define the matrix

\begin{equation} \label{eq:A6}
    \mathbf{Z} =
    \begin{pmatrix}
        \mathbf{Z}_1 &
        \\  & \mathbf{Z}_2
    \end{pmatrix}_{(m+k) \times (m+k)} \hspace{-2cm},
\end{equation}

with

\begin{equation*}
    \mathbf{Z}_1 =
    \begin{pmatrix}
        z_1 &
        \\ & \ddots 
        \\ & & z_m 
    \end{pmatrix}_{m \times m} \hspace{-0.85cm}, \quad \quad \quad
    \mathbf{Z}_2 =
    \begin{pmatrix}
        z_{m+1} &
        \\ & \ddots 
        \\ & & z_{m+k} 
    \end{pmatrix}_{k \times k} \hspace{-0.65cm},
\end{equation*}

and the Casorati matrix $\mathbf{W}$ (see, e.g. \cite[Section 1.1]{AmodioBrugnano1996} and \cite[Section 2.1]{LakshmikanthamTrigiante1988} for precise definitions) partitioned as

\begin{equation*}
    \mathbf{W} =
    \begin{pmatrix} 
        \mathbf{W}_{11} & \mathbf{W}_{12}
        \\ \mathbf{W}_{21} & \mathbf{W}_{22}
    \end{pmatrix}_{(m+k) \times (m+k)} \hspace{-2cm},
\end{equation*}

with $\mathbf{W}_{12} \in \mathbb{R}^{k \times k}$ and $\mathbf{W}_{21} \in \mathbb{R}^{m \times m}$.

Suppose from now on the simplest case in which $q^{\mathbf{C}}$ is of the type $(m_1,m_2,k)$ and all its zeros are simple. In the case where $q^{\mathbf{C}}$ is of type $(m,k_1,k_2)$, it is sufficient to consider the families $\{\mathbf{C}_n^{\top}\}_n$ and $\{\widehat{\mathbf{C}}_n^{\top}\}_n$, while in case of non-weakly well-conditioning, or multiple zeros, proofs of \eqref{eq:A3} and \eqref{eq:A4} can be obtained by similar arguments.

\noindent\textbf{Step 1.}  Define the lower triangular block matrices

\begin{equation} \label{eq:A7}
    \mathbf{E}_{\mathbf{C}_n^{(0)}} = \begin{pmatrix}
    \mathbf{E}_{11} & \mathbf{0}_{k} \vspace{0.05cm} \\
    \mathbf{C}_n^{(0)} & \mathbf{E}_{22}
    \end{pmatrix}_{(n+k) \times (n+k)} \quad \hspace{-2.2cm}, \quad \quad  \hspace{1.6cm} \mathbf{E}_{\mathbf{C}_n^{(1)}} = \begin{pmatrix}
    \mathbf{E}_{11} & \mathbf{0}_{k} \vspace{0.05cm} \\
    \mathbf{C}_n^{(1)} & \mathbf{E}_{22}
    \end{pmatrix}_{(n+k) \times (n+k)} \hspace{-1.85cm},
\end{equation}

with

\begin{equation*}
    \mathbf{E}_{11} =
    \begin{pmatrix}
        \mathbf{I}_k & \mathbf{0}_{k,n-k}
    \end{pmatrix}_{k \times n}
    \quad \quad  \text{and} \quad \quad 
    \mathbf{E}_{22} = 
    \left(
    \begin{array}{c}
        \mathbf{0}_{n-k,k} \\[0.15cm] \hline
        \begin{matrix}
            c_k &  \\
            \vdots & \ddots  \\
            c_1 & \ldots & c_k
        \end{matrix}
    \end{array}
    \right)_{n \times k}
    \hspace{-0.65cm},
\end{equation*}

where $\mathbf{I}_k \in \mathbb{R}^{k \times k}$ is the identity matrix. The matrices $\mathbf{E}_{\mathbf{C}_n^{(0)}}$ and $\mathbf{E}_{\mathbf{C}_n^{(1)}}$ are nonsingular since the elements on their diagonals are not zero. Then, by virtue of Lemma \ref{lem:A1}, the following decompositions are true

\begin{equation*}
    \mathbf{E}_{\mathbf{C}_n^{(0)}}^{-1} =
    \begin{pmatrix}
    \mathbf{X}_{11}^{(0)} & \mathbf{X}_{12} \vspace{0.1cm} \\
    \mathbf{X}_{21}^{(0)} & \mathbf{X}_{22}
    \end{pmatrix}_{(n+k) \times (n+k)} \quad \hspace{-2.2cm}, \quad \hspace{1.6cm} \quad 
    \mathbf{E}_{\mathbf{C}_n^{(1)}}^{-1} =
    \begin{pmatrix}
    \mathbf{X}_{11}^{(1)} & \mathbf{X}_{12} \vspace{0.1cm} \\
    \mathbf{X}_{21}^{(1)} & \mathbf{X}_{22}
    \end{pmatrix}_{(n+k) \times (n+k)} \hspace{-1.85cm},
\end{equation*}

and with \eqref{eq:A1}, we compute

\begin{equation} \label{eq:A8}
    \mathbf{H}_n^{(1)} = (\mathbf{C}_n^{(1)})^{-1} - (\mathbf{C}_n^{(0)})^{-1} = \bigl(\mathbf{X}_{11}^{(0)} (\mathbf{X}_{21}^{(0)})^{-1}-\mathbf{X}_{11}^{(1)} (\mathbf{X}_{21}^{(1)})^{-1} \bigr) \mathbf{X}_{22}.
\end{equation}

We now show that, for $n$ sufficiently large,

\begin{equation*}
    \mathbf{H}_n^{(1)}[\ell,j] =  \mathcal{O}\left(\frac{|z_m|^\ell}{|z_{m+1}|^j}\right), \quad \ell = k+1,\ldots,n \quad \text{and} \quad j = 1,\ldots, n.
\end{equation*}

The first $k$ columns of $\mathbf{E}^{-1}_{\mathbf{C}_n^{(0)}}$ and $\mathbf{E}^{-1}_{\mathbf{C}_n^{(1)}}$ are obtained by solving the block linear systems

\begin{equation*}
    \mathbf{E}_{\mathbf{C}_n^{(0)}} 
    \begin{pmatrix}
        \mathbf{X}_{11}^{(0)} \vspace{0.1cm} \\ \mathbf{X}_{21}^{(0)}
    \end{pmatrix}
    = 
    \begin{pmatrix}
        \textbf{I}_k
        \\
        \mathbf{0}_{n,k}
    \end{pmatrix}, \quad \quad \quad
    \mathbf{E}_{\mathbf{C}_n^{(1)}} 
    \begin{pmatrix}
        \mathbf{X}_{11}^{(1)}
        \vspace{0.1cm} \\ \mathbf{X}_{21}^{(1)}
    \end{pmatrix}
    = 
    \begin{pmatrix}
        \textbf{I}_k
        \\
        \mathbf{0}_{n,k}
    \end{pmatrix}.
\end{equation*}

Exactly as in \cite[Equation (21)]{AmodioBrugnano1996} it is possible to show that the $\ell^{\operatorname{th}}$ row of $\mathbf{X}_{11}^{(0)}$ satisfies the relation

\begin{equation} \label{eq:A9}
\begin{aligned}
    \begin{pmatrix}
    \mathbf{X}_{11}^{(0)}[\ell,1], & \ldots \, , & \mathbf{X}_{11}^{(0)}[\ell,k] 
    \end{pmatrix}^\top & = 
    \mathbf{e}_\ell^\top \mathbf{X}_{11}^{(0)} = \mathbf{1}_{m+k}^{\top} \mathbf{Z}^{\ell-1}
    \begin{pmatrix}
        \mathbf{G}_1^{(0)} \vspace{0.1cm} \\
        \mathbf{G}_2^{(0)}
    \end{pmatrix}, \quad \ell = 1, \ldots, n
\end{aligned}    
\end{equation}

where $\mathbf{e}_\ell$ is the $\ell^{\operatorname{th}}$ vector of the canonical base of $\mathbb{R}^n$, $\mathbf{1}_{m+k} = (1,\ldots,1)^{\top} \in \mathbb{R}^{m+k}$, $\mathbf{Z}$ is defined in \eqref{eq:A6}, and the matrices $\mathbf{G}_1^{(0)} \in \mathbb{R}^{m \times k}$ and $\mathbf{G}_2^{(0)} \in \mathbb{R}^{k \times k}$ are defined by

\begin{equation*}
    \begin{pmatrix}
        \mathbf{G}_1^{(0)} \vspace{0.1cm} \\
        \mathbf{G}_2^{(0)}
    \end{pmatrix}
    = \mathbf{W}^{-1} \mathbf{X}_{11}^{(0)}[1:m+k,1:k], 
\end{equation*}

with $\mathbf{W}$ the Casorati matrix, and $\mathbf{X}_{11}^{(0)}[1:m+k,1:k]$ the $(m+k) \times k$ top-left block of $\mathbf{X}_{11}^{(0)}$ in standard indices notation. A similar expression is obtained for the $\ell^{\operatorname{th}}$ row of $\mathbf{X}_{11}^{(1)}$ with the difference that the top-left block of $\mathbf{C}_n^{(1)}$ in \eqref{eq:A2} must be also considered, from which the analogue of \eqref{eq:A9} only holds for $\ell \ge k+1$. With greater details, we obtain

\begin{equation*}
    \mathbf{e}_\ell^\top \mathbf{X}_{11}^{(1)} = \mathbf{1}_{m+k}^{\top} \mathbf{Z}^{\ell-1-k}
    \begin{pmatrix}
        \mathbf{G}_1^{(1)} \vspace{0.1cm} \\
        \mathbf{G}_2^{(1)}
    \end{pmatrix}, \quad \ell = k+1,\ldots, n
\end{equation*}

with the matrices $\mathbf{G}_1^{(1)} \in \mathbb{R}^{m \times k}$ and $\mathbf{G}_2^{(1)} \in \mathbb{R}^{k \times k}$ defined by

\begin{equation} \label{eq:A10}
    \begin{pmatrix}
        \mathbf{G}_1^{(1)} \vspace{0.1cm} \\
        \mathbf{G}_2^{(1)}
    \end{pmatrix}
    = \mathbf{W}^{-1} \mathbf{X}_{11}^{(1)}[k+1:m+2k,1:k].
\end{equation}

Note that the block $\mathbf{X}_{11}^{(1)}[k+1:m+2k,1:k]$ depends on the top-left block perturbation of size $(m+k) \times k$ of $\mathbf{C}_n^{(1)}$.

For $n$ sufficient large, similarly, we compute

\begin{equation} \label{eq:A11}
    \begin{aligned}
        \mathbf{X}_{21}^{(0)} & =
        \begin{pmatrix}
            \mathbf{W}_{11} & \mathbf{W}_{12}
        \end{pmatrix}
        \mathbf{Z}^n
        \begin{pmatrix}
            \mathbf{G}_1^{(0)} \vspace{0.1cm} \\
            \mathbf{G}_2^{(0)}
        \end{pmatrix}
     = \mathbf{W}_{12} \mathbf{Z}_2^n \mathbf{G}_2^{(0)} + \mathcal{O}\left(\left|\frac{z_m}{z_{m+1}}\right|^n\right),
    \\ 
        \mathbf{X}_{21}^{(1)} & =
        \begin{pmatrix}
            \mathbf{W}_{11} & \mathbf{W}_{12}
        \end{pmatrix}
        \mathbf{Z}^{n-k}
        \begin{pmatrix}
            \mathbf{G}_1^{(1)} \vspace{0.1cm} \\
            \mathbf{G}_2^{(1)}
        \end{pmatrix}
     = \mathbf{W}_{12} \mathbf{Z}_2^{n-k} \mathbf{G}_2^{(1)} + \mathcal{O}\left(\left|\frac{z_m}{z_{m+1}}\right|^{n-k}\right).
    \end{aligned}
\end{equation}

Since it is assumed that $\mathbf{C}_n^{(0)}$ and $\mathbf{C}_n^{(1)}$ are nonsingular, for sufficiently large $n$, by Lemma \ref{lem:A1} also $\mathbf{G}_2^{(1)}$ and $\mathbf{G}_2^{(0)}$ are.

Finally, $\mathbf{X}_{22}$ has been calculated in \cite[Equation (25)]{AmodioBrugnano1996}, and it holds true

\begin{equation} \label{eq:A12}
    \mathbf{X}_{22} \mathbf{e}_j =
    \begin{pmatrix}
        \mathbf{W}_{11} & \mathbf{W}_{12}
    \end{pmatrix}
    \mathbf{Z}^{n+m-j}
    \begin{pmatrix}
        \mathbf{G}_1^{(\cdot)} \vspace{0.1cm} \\
        \mathbf{G}_2^{(\cdot)}
    \end{pmatrix}, \quad j = 1,\ldots,n
\end{equation}

with the vectors $\mathbf{G}_1^{(\cdot)}$ and $\mathbf{G}_2^{(\cdot)}$ not depending on $j$, defined as

\begin{equation*}
    \begin{pmatrix}
        \mathbf{G}_1^{(\cdot)} \vspace{0.1cm} \\
        \mathbf{G}_2^{(\cdot)}
    \end{pmatrix}
    = 
    \mathbf{W}^{-1}
    \begin{pmatrix}
        0 \\ \vdots \\ 0 \\ c_k^{-1}
    \end{pmatrix}.
\end{equation*}

Combining \eqref{eq:A9}-\eqref{eq:A12}, for $\ell = k+1,\ldots,n$ and $j=1,\ldots,n$ we deduce from \eqref{eq:A8}, for $n$ sufficiently large,

\begin{align*}
    \mathbf{H}_n^{(1)}[\ell,j] & = \mathbf{e}_\ell^\top \bigl(\mathbf{X}_{11}^{(0)} (\mathbf{X}_{21}^{(0)})^{-1}-\mathbf{X}_{11}^{(1)} (\mathbf{X}_{21}^{(1)})^{-1} \bigr) \mathbf{X}_{22} \mathbf{e}_j 
    \\ & \hspace{-1cm} \approx \mathbf{1}_{m+k}^\top \mathbf{Z}^{\ell-1}
            \left(
            \begin{pmatrix}
            \mathbf{G}_1^{(0)} \\
            \mathbf{G}_2^{(0)}
            \end{pmatrix}
            (\mathbf{G}_2^{(0)})^{-1}
            - \mathbf{Z}^{-k}
            \begin{pmatrix}
            \mathbf{G}_1^{(1)} \\
            \mathbf{G}_2^{(1)}
            \end{pmatrix}
            (\mathbf{G}_2^{(1)})^{-1} \mathbf{Z}_2^k
            \right) \mathbf{Z}_2^{-n} \mathbf{W}_{12}^{-1} \mathbf{X}_{22} \mathbf{e}_j
    \\ & \hspace{-1cm} = \mathbf{1}_{m+k}^\top \mathbf{Z}_1^{\ell-1}
            \left( 
            \mathbf{G}_1^{(0)} (\mathbf{G}_2^{(0)})^{-1}
            - \mathbf{Z}_1^{-k} \mathbf{G}_1^{(1)} (\mathbf{G}_2^{(1)})^{-1} \mathbf{Z}_2^k
            \right) \mathbf{Z}_2^{-n} \mathbf{W}_{12}^{-1} \mathbf{X}_{22} \mathbf{e}_j
    \\ & \hspace{-1cm} \approx \mathbf{1}_{m+k}^\top \mathbf{Z}_1^{\ell-1}
            \left(
            \mathbf{G}_1^{(0)} (\mathbf{G}_2^{(0)})^{-1} 
            - \mathbf{Z}_1^{-k} \mathbf{G}_1^{(1)} (\mathbf{G}_2^{(1)})^{-1} \mathbf{Z}_2^k
            \right) \mathbf{Z}_2^{m-j} \mathbf{G}_2^{(\cdot)}
    \\ & \hspace{-1cm} = \mathcal{O} \left( \frac{|z_m|^\ell}{|z_{m+1}|^j} \right).
\end{align*}

From the latter, we deduce that the families $\{\mathbf{C}_n^{(0)}\}_n$ and $\{\mathbf{C}_n^{(1)}\}_n$ have the same conditioning behaviour.

\noindent\textbf{Step 2.} Consider the families of matrices $\{(\mathbf{C}_n^{(1)})^\top\}_n$ and $\{(\mathbf{C}_n^{(2)})^\top\}_n$. Since each difference $(\mathbf{C}_n^{(2)})^\top - (\mathbf{C}_n^{(1)})^\top$ has the same structure as each $\mathbf{C}_n^{(1)} - \mathbf{C}_n^{(0)}$, it is possible to proceed exactly as in \textbf{Step 1.} and bound component-wise the elements of the matrix $\mathbf{H}_n^{(2)}$. Note that the polynomial $q^{\mathbf{C}^\top}$ associated with the purely Toeplitz part of the family $\{(\mathbf{C}_n^{(1)})^\top\}_n$ has as roots the reciprocals of the roots of $q^{\mathbf{C}}$, while $m$ and $k$ now have an inverted role. Therefore, if $q^{\mathbf{C}}$ is of type $(m_1,m_2,k)$, then $q^{\mathbf{C}^\top}$ is of type $(k,m_2,m_1)$. Taking these facts into account, we deduce that, for $n$ sufficiently large,

\begin{equation*}
    \mathbf{H}_n^{(2)}[\ell,j] =  \mathcal{O}\left(\frac{|z_{n-k+1}|^{-j}}{|z_{n-k}|^{-\ell}}\right) = \mathcal{O}\left(\frac{|z_m|^\ell}{|z_{m+1}|^j}\right), 
\end{equation*}

for $\ell = m+1,\ldots,n$ and $j = k+1,\ldots, n$. As in the previous step, we conclude that the families $\{ \mathbf{C}_n^{(1)}\}_n$ and $\{ \mathbf{C}_n^{(2)}\}_n$ have the same conditioning behaviour.

\noindent\textbf{Step 3.} Let us define $\textbf{J}_n$ the exchange matrix of size $n \times n$, i.e.,

\begin{equation} \label{eq:A13}
    \textbf{J}_n = \begin{pmatrix}
    0 & \\
    1 & 0  \\
    0 & 1 & 0 \\
    \vdots &\ddots &\ddots & \ddots \\
    0 &\ldots& 0 & 1 & 0
    \end{pmatrix}_{n \times n} \hspace{-0.65cm}.
\end{equation}

Consider the families $\{\textbf{J}_n (\mathbf{C}_n^{(2)})^\top \textbf{J}_n\}_n$ and $\{\textbf{J}_n (\mathbf{C}_n^{(3)})^\top \textbf{J}_n \}_n$. Given a nonsingular matrix $\mathbf{C} \in \mathbb{R}^{n \times n}$, it holds valid $(\textbf{J}_n \mathbf{C} \textbf{J}_n)^{-1} = \textbf{J}_n \mathbf{C}^{-1} \textbf{J}_n$. Therefore, the conditioning behaviour of the families just defined is equal to that of $\{\mathbf{C}_n^{(2)}\}_n$ and $\{\mathbf{C}_n^{(3)}\}_n$, respectively. As in \textbf{Step 2.}, each difference $\textbf{J}_n (\mathbf{C}_n^{(3)})^\top \textbf{J}_n - \textbf{J}_n (\mathbf{C}_n^{(2)})^\top \textbf{J}_n$ has the same structure as each $\mathbf{C}_n^{(1)} - \mathbf{C}_n^{(0)}$, and it is possible to proceed as in \textbf{Step 1.} to bound component-wise the elements of $\mathbf{H}_n^{(3)}$. Note that in this case the polynomial $q^{\textbf{J} \mathbf{C}^\top \textbf{J}}$ associated with the Toeplitz part of the family $\{\textbf{J}_n (\mathbf{C}_n^{(2)})^\top \textbf{J}_n\}_n$ satisfies $q^{\textbf{J} \mathbf{C}^\top \textbf{J}} = q^{\mathbf{C}}$. We deduce, for $n$ sufficiently large,

\begin{equation*}
    (\textbf{J}_n (\mathbf{H}_n^{(3)})^\top \textbf{J}_n) [\ell,j] = \mathcal{O}\left(\frac{|z_m|^\ell}{|z_{m+1}|^j}\right), \quad \ell = k+1,\ldots,n \quad \text{and} \quad j = m+1,\ldots, n,
\end{equation*}

or equivalently

\begin{equation*}
    \mathbf{H}_n^{(3)} [\ell,j] = \mathcal{O}\left(\frac{|z_m|^{n-j+1}}{|z_{m+1}|^{n-\ell+1}}\right), \quad \ell = k+1,\ldots,n \quad \text{and} \quad j = m+1,\ldots, n.
\end{equation*}

We deduce the same conditioning behaviour for the families $\{ \mathbf{C}_n^{(2)}\}_n$ and $\{ \mathbf{C}_n^{(3)}\}_n$.

\noindent\textbf{Step 4.} Finally, we consider the families $\{\textbf{J}_n (\mathbf{C}_n^{(3)}) \textbf{J}_n\}_n$ and $\{\textbf{J}_n (\mathbf{C}_n^{(4)}) \textbf{J}_n \}_n$. Proceeding as in \textbf{Steps 2.} and \textbf{3.}, with estimates similar as in \textbf{Step 1.}, we obtain

\begin{equation*}
    \mathbf{H}_n^{(4)} [\ell,j] = \mathcal{O}\left(\frac{|z_m|^{n-j+1}}{|z_{m+1}|^{n-\ell+1}}\right), \quad \ell = m+1,\ldots,n \quad \text{and} \quad j = k+1,\ldots, n.
\end{equation*}

Combining the four steps concludes the proof.
\hfill \qedsymbol

