\end{equation*}

Here, $N_1, M_1, N_1, N_2$ are independent of $n$, and at least three of the four sub-blocks of the perturbed matrices in positions $[1:m,$ $k+1:m+k]$, $[m+1:m+k$, $1:k]$, $[n-k-m+1:n-k$, $n-m+1:n]$ and $[n-k+1:n$, $n-m-k+1:n-m]$ are nonsingular.

Let $\{\mathbf{C}_n\}_n$ be a family of nonsingular Toeplitz band matrices as in~\eqref{eq:41}. Let the associated polynomial $q^{\mathbf{C}}$ in \eqref{eq:42} be of type $(m_1,m_2,k)$ or $(m,k_1,k_2)$, where $m_1+m_2=m$ and $k_1+k_2=k$. From \cite[Lemma 2]{AmodioBrugnano1996}, there exist $\mathbf{L}_n, \mathbf{U}_n \in \mathbb{R}^{n \times n}$, respectively, lower and upper Toeplitz triangular matrices (see \cite[Section 3]{AmodioBrugnano1996} for the precise definition) such that

\begin{equation} \label{eq:A14}
    \mathbf{C}_n^{-1} = \mathbf{U}_n^{-1} \mathbf{L}_n^{-1} + \mathbf{H}_n^{(0)}
\end{equation}

with $\mathbf{H}_n^{(0)}$ satisfying the analogous of \eqref{eq:A4}. Consider now a family of perturbed matrices $\{\widehat{\mathbf{C}}_n\}_n$ as in the assumptions of Theorem \ref{th:45} or Remark \ref{rem:A3}. Combining \eqref{eq:A14} with \eqref{eq:A5}, we deduce that

\begin{equation*}
    \widehat{\mathbf{C}}_n^{-1} = \mathbf{U}_n^{-1} \mathbf{L}_n^{-1} + \mathbf{H}_n^{(0)} + \mathbf{H}_n^{(1)} + \mathbf{H}_n^{(2)} + \mathbf{H}_n^{(3)} + \mathbf{H}_n^{(4)}
\end{equation*}

with the same $\mathbf{L}_n$, $\mathbf{U}_n$ and $\mathbf{H}_n^{(0)}$ as in \cite{AmodioBrugnano1996}, and the four matrices $\mathbf{H}_n^{(j)}$, $j=1,\ldots,4$, characterized in the proof of Theorem \ref{th:45}.

